from odoo import api, fields, models


class ResCompany(models.Model):
    _inherit = 'res.company'

    regie_communication_prefix = fields.Char(
        string="Structured Communication Prefix", default='9',
        help="Leading digit(s) of the structured communications of the leases, to keep them apart "
             "from the references generated by Odoo for invoices.",
    )

    # Rent invoicing schedule
    regie_invoice_day = fields.Integer(
        string="Invoice Generation Day", default=20,
        help="Day of the month on which the rent invoices of a period are generated.",
    )
    regie_invoice_month_offset = fields.Selection(
        [('previous', 'Previous Month'), ('current', 'Same Month')],
        string="Generation Month", default='previous', required=True,
        help="Generate the invoice of a period during the previous month (rent paid in advance) "
             "or during the period itself.",
    )
    regie_due_day = fields.Integer(
        string="Due Day", default=1,
        help="Day of the invoiced month on which the rent is due.",
    )
    regie_rent_journal_id = fields.Many2one(
        'account.journal', string="Rent Journal", check_company=True,
        domain="[('type', '=', 'sale')]",
        help="Sales journal of the rent invoices (default: the first sales journal).",
    )
    regie_rent_account_id = fields.Many2one(
        'account.account', string="Rent Income Account", check_company=True,
        domain="[('account_type', 'in', ('income', 'income_other'))]",
    )
    regie_charge_account_id = fields.Many2one(
        'account.account', string="Charge Provisions Income Account", check_company=True,
        domain="[('account_type', 'in', ('income', 'income_other'))]",
    )

    # Indexation (Brussels rules)
    regie_index_base_year = fields.Char(
        string="Health Index Base Year", default='2013', required=True,
        help="Base year of the health index used for the indexation of the rents.",
    )
    regie_indexation_notice_days = fields.Integer(
        string="Indexation Proposal Notice (days)", default=45,
        help="Number of days before the anniversary of the lease at which the indexation proposal is created.",
    )
    regie_indexation_retroactivity_months = fields.Integer(
        string="Indexation Retroactivity (months)", default=3,
        help="The indexation applies at most this number of months before the written request.",
    )
    regie_peb_correction_cutoff_date = fields.Date(
        string="EPC Correction Cut-off Date", default=fields.Date.to_date('2022-10-14'),
        help="The EPC correction factor applies to housing leases that took effect before this date.",
    )

    def _regie_get_rent_journal(self):
        self.ensure_one()
        return self.regie_rent_journal_id or self.env['account.journal'].search([
            *self.env['account.journal']._check_company_domain(self),
            ('type', '=', 'sale'),
        ], limit=1)

    # ------------------------------------------------------------
    # DEMO
    # ------------------------------------------------------------

    @api.model
    def _regie_demo_reset_previous_company(self):
        """ Demo, run at install only. An uninstall cannot delete the demo company (chart of
        accounts) nor its partners: their xml ids survive and a reinstall reuses them. The accounting
        documents generated by the previous demo are left behind too: delete them (demo company
        only), so that the demo invoicing does not create duplicates. """
        company = self.env.ref('regie_fonciere.demo_company', raise_if_not_found=False)
        if not company:
            return
        company = company.with_context(active_test=False)
        payments = self.env['account.payment'].search([('company_id', '=', company.id)])
        moves = self.env['account.move'].search([('company_id', '=', company.id)])
        payments.filtered(lambda p: p.state != 'draft').action_draft()
        payments.with_context(force_delete=True).unlink()
        moves = moves.exists()
        moves.filtered(lambda m: m.state != 'draft').button_draft()
        moves.with_context(force_delete=True).unlink()
        mandates = self.env['account.direct.debit.mandate'].search([('company_id', '=', company.id)])
        mandates.write({'state': 'draft'})
        mandates.unlink()
        self.env['account_followup.followup.line'].search([('company_id', '=', company.id)]).unlink()

    @api.model
    def _regie_demo_setup_company(self):
        """ Demo: load the Belgian chart of accounts on the demo company, give the administrator
        access to it and configure the rent income accounts. Idempotent. """
        company = self.env.ref('regie_fonciere.demo_company', raise_if_not_found=False)
        if not company:
            return
        if not company.chart_template:
            # _load() rather than try_loading(): the latter warns when the registry is not fully
            # loaded unless the chart's own demo (sample invoices) is installed, which we don't want.
            self.env['account.chart.template']._load('be_comp', company, install_demo=False)
        for user in (self.env.ref('base.user_admin'), self.env.ref('base.user_root')):
            if company not in user.company_ids:
                user.company_ids = [(4, company.id)]
        company._regie_demo_setup_income_accounts()

    def _regie_demo_setup_income_accounts(self):
        """ Rent income: 700100 (class 70, turnover); charge provisions: 743100 (under 743,
        miscellaneous operating income). See CLAUDE.md. """
        Account = self.env['account.account'].with_company(self)
        for field, code, name in (
            ('regie_rent_account_id', '700100', "Loyers"),
            ('regie_charge_account_id', '743100', "Provisions pour charges locatives"),
        ):
            if self[field]:
                continue
            account = Account.search([*Account._check_company_domain(self), ('code', '=', code)], limit=1)
            if not account:
                account = Account.create({
                    'code': code,
                    'name': name,
                    'account_type': 'income' if code.startswith('70') else 'income_other',
                    'company_ids': [(6, 0, self.ids)],
                })
            self[field] = account
